package com.example.lending.adapter.out.persistence;

import com.example.lending.domain.CreditCheck;
import com.example.lending.domain.Loan;

import java.util.Arrays;
import java.util.List;

class LoanMapper {

    private static final String REASON_CODE_DELIMITER = ",";

    Loan toDomain(LoanJpaEntity entity) {
        CreditCheck creditCheck = new CreditCheck(entity.isCreditApproved(), entity.getCreditScore(),
                splitReasonCodes(entity.getCreditReasonCodes()), entity.getCreditCheckedAt(),
                entity.getCreditProviderName(), entity.getCreditProviderVersion());
        return Loan.reconstitute(entity.getId(), entity.getBookId(), entity.getMemberId(), entity.getLoanedAt(),
                entity.getDueAt(), entity.getReturnedAt(), creditCheck);
    }

    LoanJpaEntity toEntity(Loan loan) {
        CreditCheck creditCheck = loan.getCreditCheck();
        return new LoanJpaEntity(loan.getId(), loan.getBookId(), loan.getMemberId(), loan.getLoanedAt(),
                loan.getDueAt(), loan.getReturnedAt(), creditCheck.approved(), creditCheck.score(),
                String.join(REASON_CODE_DELIMITER, creditCheck.reasonCodes()), creditCheck.checkedAt(),
                creditCheck.providerName(), creditCheck.providerVersion());
    }

    private static List<String> splitReasonCodes(String reasonCodes) {
        if (reasonCodes == null || reasonCodes.isEmpty()) {
            return List.of();
        }
        return Arrays.asList(reasonCodes.split(REASON_CODE_DELIMITER));
    }
}
package com.example.lending.adapter.out.persistence;

import com.example.lending.application.port.out.LoadLoanPort;
import com.example.lending.application.port.out.SaveLoanPort;
import com.example.lending.domain.Loan;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Sort;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.Optional;
import java.util.UUID;

@Component
public class LoanPersistenceAdapter implements SaveLoanPort, LoadLoanPort {

    private final LoanJpaRepository loanJpaRepository;
    private final LoanMapper loanMapper = new LoanMapper();

    public LoanPersistenceAdapter(LoanJpaRepository loanJpaRepository) {
        this.loanJpaRepository = loanJpaRepository;
    }

    @Override
    public void saveLoan(Loan loan) {
        loanJpaRepository.save(loanMapper.toEntity(loan));
    }

    @Override
    public Optional<Loan> loadLoan(UUID loanId) {
        return loanJpaRepository.findById(loanId).map(loanMapper::toDomain);
    }

    @Override
    public long countActiveLoansByMemberId(UUID memberId) {
        return loanJpaRepository.countByMemberIdAndReturnedAtIsNull(memberId);
    }

    @Override
    public List<Loan> loadActiveLoansByMemberId(UUID memberId, int page, int size) {
        PageRequest pageRequest = PageRequest.of(page, size, Sort.by("loanedAt", "id"));
        return loanJpaRepository.findByMemberIdAndReturnedAtIsNull(memberId, pageRequest)
                .getContent().stream()
                .map(loanMapper::toDomain)
                .toList();
    }

    @Override
    public List<Loan> loadLoansByMemberId(UUID memberId) {
        return loanJpaRepository.findByMemberIdOrderByLoanedAtDescIdDesc(memberId).stream()
                .map(loanMapper::toDomain)
                .toList();
    }
}
package com.example.lending.adapter.out.persistence;

import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;

import java.util.List;
import java.util.UUID;

public interface LoanJpaRepository extends JpaRepository<LoanJpaEntity, UUID> {

    long countByMemberIdAndReturnedAtIsNull(UUID memberId);

    Page<LoanJpaEntity> findByMemberIdAndReturnedAtIsNull(UUID memberId, Pageable pageable);

    List<LoanJpaEntity> findByMemberIdOrderByLoanedAtDescIdDesc(UUID memberId);
}

