package com.example.lending.architecture;

import com.example.lending.architecture.HexagonalRules.NamedRule;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.tngtech.archunit.core.domain.JavaClasses;
import com.tngtech.archunit.core.importer.ImportOption.DoNotIncludeTests;
import com.tngtech.archunit.junit.AnalyzeClasses;
import com.tngtech.archunit.junit.ArchTag;
import com.tngtech.archunit.junit.ArchTest;
import com.tngtech.archunit.lang.EvaluationResult;
import org.junit.jupiter.api.Tag;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

/**
 * 이 프로젝트의 아키텍처 규칙 R1~R7을 검사한다. 규칙당 테스트 1개.
 * 각 테스트는 실패 여부와 관계없이, 지금까지 실행된 규칙 결과로 build/arch/lending.json을 다시 쓴 뒤 assert한다.
 * 따라서 tests_executed는 실제로 실행된 규칙 테스트 수이며, 규칙 수(7)와 같을 때 모든 규칙이 검사된 것이다.
 *
 * <p>@Tag만으로는 ArchUnit JUnit5 엔진 테스트가 태그 필터되지 않으므로 @ArchTag를 반드시 함께 단다.
 */
@Tag("arch")
@ArchTag("arch")
@AnalyzeClasses(packages = ArchitectureTest.BASE_PACKAGE, importOptions = DoNotIncludeTests.class)
class ArchitectureTest {

    static final String BASE_PACKAGE = "com.example.lending";
    private static final Path REPORT = Path.of("build", "arch", "lending.json");

    private static final List<NamedRule> RULES = HexagonalRules.forBasePackage(BASE_PACKAGE);
    private static final Set<String> RULE_IDS_COVERED_BY_THIS_CLASS = Set.of("R1", "R2", "R3", "R4", "R5", "R6", "R7");
    private static final Map<String, EvaluationResult> RESULTS = new HashMap<>();

    @ArchTest
    void r1_domain_no_outward_deps(JavaClasses classes) throws IOException {
        evaluate("R1", classes);
    }

    @ArchTest
    void r2_application_no_adapter_deps(JavaClasses classes) throws IOException {
        evaluate("R2", classes);
    }

    @ArchTest
    void r3_adapters_independent(JavaClasses classes) throws IOException {
        evaluate("R3", classes);
    }

    @ArchTest
    void r4_no_layer_cycles(JavaClasses classes) throws IOException {
        evaluate("R4", classes);
    }

    @ArchTest
    void r5_domain_no_framework_annotations(JavaClasses classes) throws IOException {
        evaluate("R5", classes);
    }

    @ArchTest
    void r6_ports_are_interfaces_implemented_in_adapters(JavaClasses classes) throws IOException {
        evaluate("R6", classes);
    }

    @ArchTest
    void r7_only_three_top_level_packages(JavaClasses classes) throws IOException {
        evaluate("R7", classes);
    }

    private static synchronized void evaluate(String ruleId, JavaClasses classes) throws IOException {
        Set<String> ruleIds = RULES.stream().map(NamedRule::id).collect(Collectors.toSet());
        if (!ruleIds.equals(RULE_IDS_COVERED_BY_THIS_CLASS)) {
            throw new AssertionError("HexagonalRules defines " + ruleIds + " but ArchitectureTest has test methods for "
                    + RULE_IDS_COVERED_BY_THIS_CLASS + " — add/remove a test method per rule");
        }
        if (classes.stream().noneMatch(c -> c.getPackageName().startsWith(BASE_PACKAGE + ".domain"))) {
            throw new AssertionError("no classes imported under " + BASE_PACKAGE + ".domain — wrong base package?");
        }

        NamedRule namedRule = RULES.stream().filter(r -> r.id().equals(ruleId)).findFirst().orElseThrow();
        EvaluationResult result = namedRule.rule().evaluate(classes);
        RESULTS.put(ruleId, result);
        writeReport();

        int violations = result.getFailureReport().getDetails().size();
        System.out.printf("[arch] %s %-45s %s (%d) %s%n", ruleId, namedRule.name(),
                violations == 0 ? "PASS" : "FAIL", violations, ViolationExtractor.violatingClasses(result));
        if (result.hasViolation()) {
            throw new AssertionError(ruleId + " " + namedRule.name() + " violated in " + BASE_PACKAGE + ":\n"
                    + result.getFailureReport());
        }
    }

    private static void writeReport() throws IOException {
        Map<String, EvaluationResult> executedInRuleOrder = new LinkedHashMap<>();
        RULES.stream().filter(r -> RESULTS.containsKey(r.id()))
                .forEach(r -> executedInRuleOrder.put(r.id(), RESULTS.get(r.id())));

        Files.createDirectories(REPORT.getParent());
        new ObjectMapper().enable(SerializationFeature.INDENT_OUTPUT)
                .writeValue(REPORT.toFile(), ViolationExtractor.report(executedInRuleOrder));
    }
}
package com.example.lending.architecture;

import com.tngtech.archunit.base.DescribedPredicate;
import com.tngtech.archunit.core.domain.JavaClass;
import com.tngtech.archunit.core.domain.JavaCodeUnit;
import com.tngtech.archunit.core.domain.JavaParameter;
import com.tngtech.archunit.lang.ArchCondition;
import com.tngtech.archunit.lang.ArchRule;
import com.tngtech.archunit.lang.CompositeArchRule;
import com.tngtech.archunit.lang.ConditionEvents;
import com.tngtech.archunit.lang.SimpleConditionEvent;

import java.util.List;

import static com.tngtech.archunit.base.DescribedPredicate.not;
import static com.tngtech.archunit.core.domain.JavaClass.Predicates.resideInAPackage;
import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.classes;
import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.codeUnits;
import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.noClasses;
import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.noCodeUnits;
import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.noFields;
import static com.tngtech.archunit.library.dependencies.SlicesRuleDefinition.slices;

/**
 * 이 프로젝트의 헥사고날 아키텍처 규칙 R1~R7. 기준 패키지를 인자로 받는다.
 * 번호(id)와 이름은 build/arch/lending.json 의 키로 쓰인다.
 *
 * <p>모든 규칙은 allowEmptyShould(true): 특정 레이어가 아직 없는 코드베이스에서
 * "검사 대상 없음"이 위반 1건으로 집계되지 않게 한다. 기준 패키지 오타 방어는 각 테스트가 import 결과를 직접 확인한다.
 */
public final class HexagonalRules {

    public record NamedRule(String id, String name, ArchRule rule) {
    }

    private static final String ENTITY = "jakarta.persistence.Entity";
    private static final String COMPONENT = "org.springframework.stereotype.Component";
    private static final String SERVICE = "org.springframework.stereotype.Service";
    private static final String JSON_PROPERTY = "com.fasterxml.jackson.annotation.JsonProperty";
    private static final String SPRING_BOOT_APPLICATION = "org.springframework.boot.autoconfigure.SpringBootApplication";

    private HexagonalRules() {
    }

    public static List<NamedRule> forBasePackage(String basePackage) {
        String domain = basePackage + ".domain..";
        String application = basePackage + ".application..";
        String adapter = basePackage + ".adapter..";
        String adapterIn = basePackage + ".adapter.in..";
        String adapterOut = basePackage + ".adapter.out..";
        String port = basePackage + ".application.port..";
        String portOut = basePackage + ".application.port.out..";

        // 도메인은 Bean Validation(jakarta.validation..)과 Jackson(com.fasterxml.jackson..)도 쓰지 않는다
        String r1Reason = "domain은 ..application.., ..adapter.., org.springframework.., jakarta.persistence.., "
                + "jakarta.validation.., com.fasterxml.jackson..을 의존하지 않는다";
        ArchRule r1 = noClasses().that().resideInAPackage(domain)
                .should().dependOnClassesThat().resideInAnyPackage(
                        application, adapter, "org.springframework..", "jakarta.persistence..",
                        "jakarta.validation..", "com.fasterxml.jackson..")
                .because(r1Reason)
                .allowEmptyShould(true);

        ArchRule r2 = noClasses().that().resideInAPackage(application)
                .should().dependOnClassesThat().resideInAPackage(adapter)
                .because("application은 ..adapter..를 의존하지 않는다")
                .allowEmptyShould(true);

        String r3Reason = "adapter.in과 adapter.out은 서로 의존하지 않는다";
        ArchRule r3 = CompositeArchRule
                .of(noClasses().that().resideInAPackage(adapterIn)
                        .should().dependOnClassesThat().resideInAPackage(adapterOut)
                        .because(r3Reason)
                        .allowEmptyShould(true))
                .and(noClasses().that().resideInAPackage(adapterOut)
                        .should().dependOnClassesThat().resideInAPackage(adapterIn)
                        .because(r3Reason)
                        .allowEmptyShould(true));

        // 최상위 패키지 단위 슬라이스: domain / application / adapter
        ArchRule r4 = slices().matching(basePackage + ".(*)..")
                .should().beFreeOfCycles()
                .because("레이어 간 순환 의존이 없다")
                .allowEmptyShould(true);

        // @Entity/@Component/@Service는 TYPE 대상이지만 @JsonProperty는 TYPE에 붙을 수 없으므로
        // (FIELD/METHOD/PARAMETER/ANNOTATION_TYPE) 클래스 수준 검사만으로는 절대 잡히지 않는다. 멤버·파라미터까지 본다.
        String r5Reason = "domain 클래스에 @Entity, @Component, @Service, @JsonProperty가 없다";
        ArchRule r5 = CompositeArchRule
                .of(noClasses().that().resideInAPackage(domain)
                        .should().beAnnotatedWith(ENTITY)
                        .orShould().beAnnotatedWith(COMPONENT)
                        .orShould().beAnnotatedWith(SERVICE)
                        .orShould().beAnnotatedWith(JSON_PROPERTY)
                        .because(r5Reason)
                        .allowEmptyShould(true))
                .and(noFields().that().areDeclaredInClassesThat().resideInAPackage(domain)
                        .should().beAnnotatedWith(JSON_PROPERTY)
                        .because(r5Reason)
                        .allowEmptyShould(true))
                .and(noCodeUnits().that().areDeclaredInClassesThat().resideInAPackage(domain)
                        .should().beAnnotatedWith(JSON_PROPERTY)
                        .because(r5Reason)
                        .allowEmptyShould(true))
                .and(codeUnits().that().areDeclaredInClassesThat().resideInAPackage(domain)
                        .should(notHaveParametersAnnotatedWith(JSON_PROPERTY))
                        .because(r5Reason)
                        .allowEmptyShould(true));

        // record는 포트 계약에 딸린 입력 데이터(예: LoanBookUseCase.LoanBookCommand)라서 interface 요구에서 제외한다.
        // record는 상속·구현이 불가능해 포트 역할을 할 수 없으므로 이 예외로 추상 클래스 포트가 빠져나가지 않는다.
        String r6Reason = "application.port 아래 타입은 interface이며, port.out 인터페이스의 구현체는 adapter.out에만 있다";
        ArchRule r6 = CompositeArchRule
                .of(classes().that().resideInAPackage(port)
                        .and().areNotAssignableTo(Record.class)
                        .should().beInterfaces()
                        .because(r6Reason)
                        .allowEmptyShould(true))
                .and(classes().that().areAssignableTo(resideInAPackage(portOut))
                        .and().resideOutsideOfPackage(portOut)
                        .should().resideInAPackage(adapterOut)
                        .because(r6Reason)
                        .allowEmptyShould(true));

        // base 직속 클래스 중 @SpringBootApplication 메인 클래스만 예외 (메타 어노테이션 아님, 하위 패키지 아님)
        DescribedPredicate<JavaClass> springBootMainClass = DescribedPredicate.describe(
                "@SpringBootApplication class directly in " + basePackage,
                javaClass -> javaClass.getPackageName().equals(basePackage)
                        && javaClass.isAnnotatedWith(SPRING_BOOT_APPLICATION));
        ArchRule r7 = classes().that().resideInAPackage(basePackage + "..")
                .and(not(springBootMainClass))
                .should().resideInAnyPackage(domain, application, adapter)
                .because("base 바로 아래의 최상위 패키지는 domain, application, adapter 셋뿐이어야 한다")
                .allowEmptyShould(true);

        return List.of(
                new NamedRule("R1", "domain-no-outward-deps", r1),
                new NamedRule("R2", "application-no-adapter-deps", r2),
                new NamedRule("R3", "adapters-independent", r3),
                new NamedRule("R4", "no-layer-cycles", r4),
                new NamedRule("R5", "domain-no-framework-annotations", r5),
                new NamedRule("R6", "ports-are-interfaces-implemented-in-adapters", r6),
                new NamedRule("R7", "only-three-top-level-packages", r7));
    }

    private static ArchCondition<JavaCodeUnit> notHaveParametersAnnotatedWith(String annotationName) {
        return new ArchCondition<>("not have parameters annotated with @" + annotationName) {
            @Override
            public void check(JavaCodeUnit codeUnit, ConditionEvents events) {
                for (JavaParameter parameter : codeUnit.getParameters()) {
                    if (parameter.isAnnotatedWith(annotationName)) {
                        events.add(SimpleConditionEvent.violated(codeUnit, String.format(
                                "Parameter %d of %s is annotated with @%s",
                                parameter.getIndex(), codeUnit.getFullName(), annotationName)));
                    }
                }
            }
        };
    }
}
package com.example.lending.architecture;

import com.tngtech.archunit.core.domain.Dependency;
import com.tngtech.archunit.core.domain.JavaAccess;
import com.tngtech.archunit.core.domain.JavaClass;
import com.tngtech.archunit.core.domain.JavaMember;
import com.tngtech.archunit.lang.EvaluationResult;
import com.tngtech.archunit.library.cycle_detection.Cycle;

import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.SortedSet;
import java.util.TreeSet;

/**
 * 규칙 평가 결과에서 위반의 원인 클래스(FQN)를 뽑고, 결과 리포트(lending.json) 구조를 만든다.
 * 실패 리포트 문자열을 파싱하지 않고 ArchUnit 위반 객체의 타입으로 판단한다.
 *
 * <ul>
 *   <li>{@link Dependency}, {@link JavaAccess} (R1~R3): 의존의 출발 클래스</li>
 *   <li>{@link Cycle} (R4): 순환을 이루는 의존들의 출발·도착 클래스 전부</li>
 *   <li>{@link JavaMember} (R5 필드·메서드·생성자·파라미터): 멤버의 소유 클래스</li>
 *   <li>{@link JavaClass} (R5 클래스, R6, R7): 그 클래스</li>
 * </ul>
 * 위 타입이 아닌 위반 객체가 오면 조용히 버리지 않고 예외를 던진다(집계 누락 방지).
 */
public final class ViolationExtractor {

    private ViolationExtractor() {
    }

    public static SortedSet<String> violatingClasses(EvaluationResult result) {
        SortedSet<String> classes = new TreeSet<>();
        List<String> unhandled = new ArrayList<>();
        // T=Object로 받아 원본 위반 객체를 변환 없이 받는다. 타입별 핸들러를 따로 등록하면 모르는 타입이 조용히 누락된다.
        result.handleViolations((Collection<Object> violatingObjects, String message) -> {
            for (Object violatingObject : violatingObjects) {
                if (violatingObject instanceof Dependency dependency) {
                    classes.add(dependency.getOriginClass().getName());
                } else if (violatingObject instanceof JavaAccess<?> access) {
                    classes.add(access.getOriginOwner().getName());
                } else if (violatingObject instanceof Cycle<?> cycle) {
                    for (Dependency dependency : cycle.convertTo(Dependency.class)) {
                        classes.add(dependency.getOriginClass().getName());
                        classes.add(dependency.getTargetClass().getName());
                    }
                } else if (violatingObject instanceof JavaMember member) {
                    classes.add(member.getOwner().getName());
                } else if (violatingObject instanceof JavaClass javaClass) {
                    classes.add(javaClass.getName());
                } else {
                    unhandled.add(violatingObject.getClass().getName() + ": " + message);
                }
            }
        });
        if (!unhandled.isEmpty()) {
            throw new IllegalStateException("unhandled violation object types:\n" + String.join("\n", unhandled));
        }
        if (result.hasViolation() && classes.isEmpty()) {
            throw new IllegalStateException("rule has violations but no cause class was extracted:\n"
                    + result.getFailureReport());
        }
        return classes;
    }

    /**
     * violating_classes 합집합에 들어가는 규칙. R4·R5는 by_rule에만 남긴다.
     * R4: 순환의 정상 방향 쪽 클래스(예: domain을 정방향으로 참조하는 application 클래스)까지 원인으로 잡는다.
     * 최상위 패키지 슬라이스에서 R4 순환의 잘못된 엣지는 R1 또는 R2에 이미 잡힌다.
     * R5: 4개 어노테이션이 모두 R1 블랙리스트 패키지라서 원인 클래스가 항상 R1의 부분집합이다(R5 ⊂ R1).
     */
    public static final List<String> PRIMARY_RULES = List.of("R1", "R2", "R3", "R6", "R7");

    /**
     * 결과 리포트 구조. {@code resultsByRuleId}는 실행된 규칙만 규칙 순서대로 담는다
     * (실행되지 않은 규칙을 0으로 기록하지 않기 위해). tests_executed = 실행된 규칙 테스트 수.
     */
    public static Map<String, Object> report(Map<String, EvaluationResult> resultsByRuleId) {
        SortedSet<String> primaryClasses = new TreeSet<>();
        Map<String, Object> byRule = new LinkedHashMap<>();
        resultsByRuleId.forEach((ruleId, result) -> {
            SortedSet<String> classes = violatingClasses(result);
            if (PRIMARY_RULES.contains(ruleId)) {
                primaryClasses.addAll(classes);
            }
            Map<String, Object> entry = new LinkedHashMap<>();
            entry.put("count", result.getFailureReport().getDetails().size());
            entry.put("classes", List.copyOf(classes));
            byRule.put(ruleId, entry);
        });

        Map<String, Object> report = new LinkedHashMap<>();
        report.put("tests_executed", resultsByRuleId.size());
        report.put("primary_rules", PRIMARY_RULES);
        report.put("violating_classes", primaryClasses.size());
        report.put("violating_classes_list", List.copyOf(primaryClasses));
        report.put("by_rule", byRule);
        return report;
    }
}
