import java.time.Instant;
import java.time.LocalDate;
import java.util.Arrays;
import java.util.List;
import java.util.UUID;

@Entity
@Table(name = "loan")
public class LoanJpaEntity {

    private static final String REASON_CODE_DELIMITER = ",";

    @Id
    private UUID id;

    @Column(nullable = false)
    private UUID bookId;

    @Column(nullable = false)
    private UUID memberId;

    @Column(nullable = false)
    private LocalDate loanedAt;

    @Column(nullable = false)
    private LocalDate dueAt;

    private LocalDate returnedAt;

    @Column(nullable = false)
    private boolean creditApproved;

    @Column(nullable = false)
    private int creditScore;

    @Column(nullable = false, length = 1000)
    private String creditReasonCodes;

    @Column(nullable = false)
    private Instant creditCheckedAt;

    private String creditProviderName;

    private String creditProviderVersion;

    protected LoanJpaEntity() {
    }

    private LoanJpaEntity(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt, LocalDate returnedAt,
                          boolean creditApproved, int creditScore, String creditReasonCodes, Instant creditCheckedAt,
                          String creditProviderName, String creditProviderVersion) {
        this.id = id;
        this.bookId = bookId;
        this.memberId = memberId;
        this.loanedAt = loanedAt;
        this.dueAt = dueAt;
        this.returnedAt = returnedAt;
        this.creditApproved = creditApproved;
        this.creditScore = creditScore;
        this.creditReasonCodes = creditReasonCodes;
        this.creditCheckedAt = creditCheckedAt;
        this.creditProviderName = creditProviderName;
        this.creditProviderVersion = creditProviderVersion;
    }

    static LoanJpaEntity from(Loan loan) {
        CreditCheck creditCheck = loan.getCreditCheck();
        return new LoanJpaEntity(loan.getId(), loan.getBookId(), loan.getMemberId(), loan.getLoanedAt(),
                loan.getDueAt(), loan.getReturnedAt(), creditCheck.approved(), creditCheck.score(),
                String.join(REASON_CODE_DELIMITER, creditCheck.reasonCodes()), creditCheck.checkedAt(),
                creditCheck.providerName(), creditCheck.providerVersion());
    }

    Loan toDomain() {
        CreditCheck creditCheck = new CreditCheck(creditApproved, creditScore, splitReasonCodes(creditReasonCodes),
                creditCheckedAt, creditProviderName, creditProviderVersion);
        return Loan.reconstitute(id, bookId, memberId, loanedAt, dueAt, returnedAt, creditCheck);
    }

    private static List<String> splitReasonCodes(String reasonCodes) {
        if (reasonCodes == null || reasonCodes.isEmpty()) {
            return List.of();
        }
        return Arrays.asList(reasonCodes.split(REASON_CODE_DELIMITER));
    }
}

